<?php declare(strict_types=1); require __DIR__.'/action-common.php';admin_post();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);try{if($id===false||!$application->adminCompanies()->find($id))throw new InvalidArgumentException('Empresa não encontrada.');$data=admin_company_data($_POST);$sameDocument=$application->adminCompanies()->findByDocument($data['documento']);if($sameDocument&&(int)$sameDocument['id']!==(int)$id)throw new InvalidArgumentException('Já existe outra empresa com esse documento.');$application->adminCompanies()->update((int)$id,$data);$session->flash('success','Dados da empresa atualizados.');admin_action_redirect('adm/empresa.php?id='.$id);}catch(Throwable $e){admin_action_error($e,$id===false?'adm/empresas.php':'adm/empresa.php?id='.$id);}
